problem:
Problem description
- There is a set $$\mathcal{R}$$ of raw materials and a set $$\mathcal{P}$$ of candy brands, planned over a time horizon $$\mathcal{T}$$ of monthly periods.
- Each raw material $$r \in \mathcal{R}$$ has a unit purchase cost $$c_r$$ and an available quantity limit $$\bar{q}_{r,t}$$ in each period $$t \in \mathcal{T}$$.
- Each product $$p \in \mathcal{P}$$ has a unit processing fee $$f_p$$ and a unit selling price $$s_p$$.
- The recipe of each product is governed by raw-material content requirements. For each pair $$\left(r,p\right)$$, the allowable fraction of raw material $$r$$ in product $$p$$ may have a lower bound $$\underline{\alpha}_{r,p}$$, an upper bound $$\overline{\alpha}_{r,p}$$, or both.
- The planning goal is to choose monthly production quantities and feasible ingredient allocations so that total profit over $$\mathcal{T}$$ is maximized.
- The business rules are:
  - Production quantities must be nonnegative.
  - The ingredient mix used for each product must satisfy all applicable minimum and maximum content requirements.
  - The total use of each raw material in any month must not exceed its available monthly limit.
  - Revenue is earned from selling produced candy, while raw material purchase costs and processing fees are incurred.
  - Any product or raw material pair without a stated bound is unrestricted except for feasibility and availability.
- A solution is represented by:
  - $$x_{p,t}$$: the quantity of product $$p$$ produced in period $$t$$.
  - $$y_{r,p,t}$$: the quantity of raw material $$r$$ allocated to product $$p$$ in period $$t$$, if ingredient allocation is modeled explicitly.
  - $$z$$: the total profit achieved over the planning horizon.

Input Format
{
  "sets": {
    "raw_materials": "$$\mathcal{R}$$",
    "products": "$$\mathcal{P}$$",
    "periods": "$$\mathcal{T}$$"
  },
  "parameters": {
    "composition_lower": {
      "symbol": "$$\\underline{\\alpha}_{r,p}$$",
      "shape": "$$|\\mathcal{R}|\\times|\\mathcal{P}|$$",
      "meaning": "Minimum allowable fraction of raw material $$r$$ in product $$p$$; entries may be $$\\varnothing$$ when no lower bound exists."
    },
    "composition_upper": {
      "symbol": "$$\\overline{\\alpha}_{r,p}$$",
      "shape": "$$|\\mathcal{R}|\\times|\\mathcal{P}|$$",
      "meaning": "Maximum allowable fraction of raw material $$r$$ in product $$p$$; entries may be $$\\varnothing$$ when no upper bound exists."
    },
    "raw_material_cost": {
      "symbol": "$$c_r$$",
      "shape": "$$|\\mathcal{R}|$$",
      "meaning": "Unit procurement cost of raw material $$r$$."
    },
    "raw_material_availability": {
      "symbol": "$$\\bar{q}_{r,t}$$",
      "shape": "$$|\\mathcal{R}|\\times|\\mathcal{T}|$$",
      "meaning": "Maximum quantity of raw material $$r$$ available in period $$t$$."
    },
    "processing_fee": {
      "symbol": "$$f_p$$",
      "shape": "$$|\\mathcal{P}|$$",
      "meaning": "Unit processing fee for product $$p$$."
    },
    "selling_price": {
      "symbol": "$$s_p$$",
      "shape": "$$|\\mathcal{P}|$$",
      "meaning": "Unit selling price for product $$p$$."
    }
  },
  "decision_variables": {
    "production_quantity": {
      "symbol": "$$x_{p,t}$$",
      "shape": "$$|\\mathcal{P}|\\times|\\mathcal{T}|$$"
    },
    "ingredient_allocation": {
      "symbol": "$$y_{r,p,t}$$",
      "shape": "$$|\\mathcal{R}|\\times|\\mathcal{P}|\\times|\\mathcal{T}|$$"
    },
    "objective_value": {
      "symbol": "$$z$$"
    }
  }
}

Output Format
{
  "production_plan": {
    "symbol": "$$x_{p,t}$$",
    "shape": "$$|\\mathcal{P}|\\times|\\mathcal{T}|$$",
    "meaning": "Optimal production quantity of each product $$p$$ in each period $$t$$."
  },
  "ingredient_plan": {
    "symbol": "$$y_{r,p,t}$$",
    "shape": "$$|\\mathcal{R}|\\times|\\mathcal{P}|\\times|\\mathcal{T}|$$",
    "meaning": "Optimal allocation of each raw material $$r$$ to each product $$p$$ in each period $$t$$, if explicitly reported."
  },
  "total_profit": {
    "symbol": "$$z$$",
    "meaning": "Maximum profit over the full horizon $$\\mathcal{T}$$."
  }
}

